// Rebuilds the offline packs of web/compiler/vendor from npm packages.
//
//   node make-packs.js            # downloads the pinned versions with `npm pack` into a temp folder
//   node make-packs.js <folder>   # or takes already unpacked packages from <folder>/<id>/package
//
// Why packs: the page must work when opened from disk (file://). There the browser forbids
// fetch() of neighbouring files and Worker from a file, so everything that runs in a worker
// (compilers, interpreters, wasm) is put into ordinary <script> files as gzip + base64 strings:
//   (self.COMPILER_PACKS = self.COMPILER_PACKS || {})["name"] = "<base64 of gzip>";
// The page loads such a file with a <script> tag only when the language is first used, passes
// the string to the worker, and the worker unpacks it with DecompressionStream('gzip').
// CodeMirror modes run on the page itself and are copied as plain files.
'use strict';
const fs = require('fs');
const os = require('os');
const path = require('path');
const zlib = require('zlib');
const { execFileSync } = require('child_process');

const PKGS = {
  clang: '@yowasp/clang@22.0.0-git20542-10',
  ruby: '@ruby/3.4-wasm-wasi@2.10.1',
  typescript: 'typescript@5.9.3',
  sqljs: 'sql.js@1.14.2',
  fengari: 'fengari-web@0.1.4',
  codemirror: 'codemirror@5.65.21',
};
const OUT = __dirname;

function fetchPackages(dir) {
  for (const [id, spec] of Object.entries(PKGS)) {
    const to = path.join(dir, id);
    if (fs.existsSync(path.join(to, 'package', 'package.json'))) continue;
    fs.mkdirSync(to, { recursive: true });
    const npm = process.platform === 'win32' ? 'npm.cmd' : 'npm';
    const name = execFileSync(npm, ['pack', spec, '--silent'], { cwd: to, shell: process.platform === 'win32' }).toString().trim().split('\n').pop();
    execFileSync('tar', ['-xzf', name], { cwd: to });
    fs.unlinkSync(path.join(to, name));
  }
}

// Precompiled header for C++: <iostream> alone takes most of the time of a small C++ compile
// (about 10 s of 11 in the browser). The runner adds it with -include-pch to sources that
// include <iostream>; the flags must be the ones it was built with, so they travel in pch.json.
const CXX_PCH = { flags: ['-std=c++20', '-O2', '-fno-exceptions'], header: '#include <iostream>\n', file: 'compiler-pch.hpp', pch: 'iostream.pch' };

const src = process.argv[2] || fs.mkdtempSync(path.join(os.tmpdir(), 'compiler-packs-'));
if (!process.argv[2]) fetchPackages(src);
const pkg = (id, ...p) => path.join(src, id, 'package', ...p);
const read = (id, ...p) => fs.readFileSync(pkg(id, ...p));
const version = (id) => JSON.parse(read(id, 'package.json')).version;

function writePack(file, entries, note) {
  let body = '// ' + note + '\n// Generated by vendor/make-packs.js - do not edit. gzip + base64 per entry.\n' +
    '(function (P) {\n';
  for (const [name, buf] of Object.entries(entries)) {
    const gz = zlib.gzipSync(buf, { level: 9 });
    body += 'P[' + JSON.stringify(name) + '] = "' + gz.toString('base64') + '";\n';
  }
  body += '})(self.COMPILER_PACKS = self.COMPILER_PACKS || {});\n';
  fs.mkdirSync(path.dirname(path.join(OUT, file)), { recursive: true });
  fs.writeFileSync(path.join(OUT, file), body);
  console.log(file, (body.length / 1048576).toFixed(2), 'MB');
}

// --- C / C++: YoWASP Clang (clang + lld + wasi-libc + libc++, all built for WebAssembly) ---
// gen/bundle.js is an ES module that finds its wasm next to itself (import.meta.url). The worker
// runs it as a classic script, so import.meta.url becomes a fixed fake address (the worker
// answers fetch() for it from the pack) and the export list becomes a global.
{
  let bundle = read('clang', 'gen', 'bundle.js').toString('utf8');
  const metas = bundle.split('import.meta.url').length - 1;
  bundle = bundle.split('import.meta.url').join('self.CLANG_BASE_URL');
  const exp = /\nexport \{([^}]*)\};?\s*$/.exec(bundle);
  if (!exp || metas < 2) throw new Error('unexpected @yowasp/clang bundle layout');
  bundle = bundle.slice(0, exp.index) + '\nself.YoWASPClang = {' + exp[1] + '};\n';
  const v = version('clang');
  writePack('clang/clang-core.pack.js', { 'llvm.core.wasm': read('clang', 'gen', 'llvm.core.wasm') },
    '@yowasp/clang ' + v + ': llvm.core.wasm (clang and lld)');
  writePack('clang/clang-rest.pack.js', {
    'bundle.js': Buffer.from(bundle, 'utf8'),
    'llvm.core2.wasm': read('clang', 'gen', 'llvm.core2.wasm'),
    'llvm.core3.wasm': read('clang', 'gen', 'llvm.core3.wasm'),
    'llvm.core4.wasm': read('clang', 'gen', 'llvm.core4.wasm'),
    'llvm-resources.tar': read('clang', 'gen', 'llvm-resources.tar'),
  }, '@yowasp/clang ' + v + ': runtime, small modules, headers and libraries (sysroot)');
}

async function makePch() {
  const { pathToFileURL } = require('url');
  const { runClang } = await import(pathToFileURL(pkg('clang', 'gen', 'bundle.js')).href);
  let err = '';
  const dec = new TextDecoder();
  const t0 = Date.now();
  const out = await runClang(['clang++', ...CXX_PCH.flags, '-Xclang', '-fno-pch-timestamp', '-x', 'c++-header', CXX_PCH.file, '-o', CXX_PCH.pch],
    { [CXX_PCH.file]: CXX_PCH.header }, { stderr: (b) => { if (b) err += dec.decode(b); }, fetchProgress: () => {} });
  if (!out || !out[CXX_PCH.pch]) throw new Error('precompiled header failed: ' + err);
  writePack('clang/clang-pch.pack.js', { [CXX_PCH.pch]: Buffer.from(out[CXX_PCH.pch]), 'pch.json': Buffer.from(JSON.stringify(CXX_PCH)) },
    '@yowasp/clang ' + version('clang') + ': precompiled <iostream> for C++ (' + ((Date.now() - t0) / 1000).toFixed(0) + ' s to build)');
}

// --- Ruby: ruby.wasm (CRuby 3.4 + standard library) and its JS glue ---
writePack('ruby/ruby.pack.js', {
  'ruby+stdlib.wasm': read('ruby', 'dist', 'ruby+stdlib.wasm'),
  'browser.umd.js': read('ruby', 'dist', 'browser.umd.js'),
}, '@ruby/3.4-wasm-wasi ' + version('ruby'));

// --- TypeScript: the compiler and the standard library declarations up to ES2022 ---
{
  const libs = {};
  const want = ['lib.es2022.d.ts'];
  while (want.length) {
    const f = want.pop();
    if (libs[f]) continue;
    const text = read('typescript', 'lib', f).toString('utf8');
    libs[f] = text;
    for (const m of text.matchAll(/\/\/\/\s*<reference\s+lib="([^"]+)"/g)) want.push('lib.' + m[1] + '.d.ts');
  }
  writePack('typescript/typescript.pack.js', {
    'typescript.js': read('typescript', 'lib', 'typescript.js'),
    'lib.json': Buffer.from(JSON.stringify(libs), 'utf8'),
  }, 'typescript ' + version('typescript') + ' (' + Object.keys(libs).length + ' lib files)');
}

// --- SQL: sql.js (SQLite compiled to WebAssembly) ---
writePack('sqljs/sqljs.pack.js', {
  'sql-wasm.js': read('sqljs', 'dist', 'sql-wasm.js'),
  'sql-wasm.wasm': read('sqljs', 'dist', 'sql-wasm.wasm'),
}, 'sql.js ' + version('sqljs'));

// --- Lua: Fengari (Lua 5.3 written in JavaScript) ---
writePack('fengari/fengari.pack.js', { 'fengari-web.js': read('fengari', 'dist', 'fengari-web.js') },
  'fengari-web ' + version('fengari'));

// --- licences next to the packs ---
const copy = (id, from, to) => fs.copyFileSync(pkg(id, ...from), path.join(OUT, to));
copy('ruby', ['dist', 'LICENSE'], 'ruby/LICENSE');
copy('ruby', ['dist', 'NOTICE'], 'ruby/NOTICE');
copy('typescript', ['LICENSE.txt'], 'typescript/LICENSE.txt');
copy('typescript', ['ThirdPartyNoticeText.txt'], 'typescript/ThirdPartyNoticeText.txt');
copy('sqljs', ['LICENSE'], 'sqljs/LICENSE');
copy('fengari', ['LICENSE'], 'fengari/LICENSE');

// --- CodeMirror 5 modes and the hint addon (the core is shared with web/python_ide) ---
fs.mkdirSync(path.join(OUT, 'codemirror'), { recursive: true });
for (const m of ['javascript', 'clike', 'lua', 'sql', 'ruby']) copy('codemirror', ['mode', m, m + '.js'], 'codemirror/' + m + '.js');
copy('codemirror', ['addon', 'hint', 'show-hint.js'], 'codemirror/show-hint.js');
copy('codemirror', ['addon', 'hint', 'show-hint.css'], 'codemirror/show-hint.css');
copy('codemirror', ['LICENSE'], 'codemirror/LICENSE');
makePch().then(() => console.log('versions:', Object.fromEntries(Object.keys(PKGS).map((id) => [id, version(id)]))));
